/// <summary>
/// Per-AOS compiled module cache result.
/// </summary>
internal final class MXTXppInterpreterCompiledModule
{
    XppInterpreter.Interpreter.Bytecode.ByteCode byteCode;
    boolean cacheHit;
    int64 parseMicroseconds;
    int64 compileMicroseconds;
}

Method.Source:
public XppInterpreter.Interpreter.Bytecode.ByteCode parmByteCode(
    XppInterpreter.Interpreter.Bytecode.ByteCode _value = byteCode)
{
    byteCode = _value;
    return byteCode;
}
